SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "马愉", "aliases": ["馬愉"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正統5年（1440年）二月，马愉以翰林院侍讲学士身份入阁。", "biography": null, "status": "draft", "id": "6beb5b7f-4f60-5820-bda4-27b3800ccd08"}, {"name": "曹鼐", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正統5年（1440年）二月，曹鼐以翰林侍讲身份入阁。", "biography": null, "status": "draft", "id": "6049135d-64fe-5c8a-b811-901a0a9575f8"}, {"name": "何文渊", "aliases": ["何文淵"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰2年（年号对照1451年）七月，何文渊出任吏部尚书。", "biography": null, "status": "draft", "id": "27355cff-bfac-5145-9909-8afd7fac7e16"}, {"name": "杨荣", "aliases": ["楊榮"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，杨荣以翰林修撰身份入直文渊阁。", "biography": null, "status": "draft", "id": "3da8dec2-a076-58ad-bf6e-5271a8173343"}, {"name": "沐昂", "aliases": ["沐景高"], "era": "明", "birth_year": null, "death_year": null, "description": "沐昂率军在师宗作战。", "biography": null, "status": "draft", "id": "d36e613f-5f8e-5b46-90eb-f144b9aa2f9a"}, {"name": "王骥", "aliases": ["王驥"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，宣德9年（年号对照1434年）三月，王骥出任兵部尚书。", "biography": null, "status": "draft", "id": "4a558c65-f1f5-51f5-90df-5aa57564c8bb"}, {"name": "于谦", "aliases": ["于謙"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统14年（年号对照1449年）八月，于谦出任兵部尚书。", "biography": null, "status": "draft", "id": "3f189404-652f-5b32-9509-a7b9157c87b2"}, {"name": "王文（明代内阁大学士）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰3年（1452年）十月，王文以太子太保、左都御史身份入阁。", "biography": null, "status": "draft", "id": "0c5a5869-dc9f-5893-b3a4-cbe279406582"}, {"name": "刘中敷", "aliases": ["劉中敷"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统元年（年号对照1436年），刘中敷出任户部尚书（原文月份缺少月数）。", "biography": null, "status": "draft", "id": "1fa6e6c4-3a0e-504a-ab00-b492ed916052"}, {"name": "思任发", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "思任发为明军征讨对象。", "biography": null, "status": "draft", "id": "98ce9322-c7cd-5041-b4aa-37cc7d6ec513"}]'::jsonb)
